package com.aditya.search.controller; import com.aditya.search.model.Document; import com.aditya.search.service.SearchService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/documents") public class SearchController { private final SearchService s; public SearchController(SearchService s){this.s=s;} @PostMapping public Document add(@RequestBody Document d){return s.add(d);} @GetMapping public List<Document> search(@RequestParam(required=false) String q){return s.search(q);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);} @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP");} }
